#!/usr/bin/env python3
"""Generate offline HTML from exact source annotations and one summary.json."""
from pathlib import Path
import hashlib,html,json
R=Path(__file__).resolve().parents[1]
M=json.loads((R/'sources/manifest.json').read_text());A=json.loads((R/'sources/line-explanations.json').read_text())
js=(R/'scripts/mechanisms.js').read_text()
css='''*{box-sizing:border-box}body{margin:0;background:#f2f6f9;color:#18354b;font:16px/1.55 system-ui,sans-serif}a{color:#176b96}header{padding:16px 24px;background:#fff;border-bottom:1px solid #d4e0e9}h1{font-size:25px;margin:3px 0 6px}h2{font-size:18px;margin:0 0 10px}.identity{font-size:13px;color:#5b7182}.intro{max-width:1100px;margin:0}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:12px 0}button,select{font:inherit;padding:6px 10px;background:#fff;border:1px solid #a9becd;border-radius:6px;cursor:pointer}button:hover{background:#e6f2fa}input[type=range]{min-width:120px;flex:1}main{padding:18px 24px}.layout{display:grid;grid-template-columns:minmax(350px,.95fr) minmax(430px,1.3fr);gap:18px;align-items:start}.panel{background:white;padding:16px;border:1px solid #d4e0e9;border-radius:10px;min-width:0}#graph{width:100%;height:250px}#message{min-height:54px;font-weight:600;color:#165b70}#state{font:13px/1.5 ui-monospace,monospace;max-height:245px;overflow:auto;background:#f5f8fa;padding:12px}#code{height:65vh;min-height:350px;overflow:auto;resize:vertical;border:1px solid #dbe5ec;border-radius:6px}.code-row{display:grid;grid-template-columns:42px minmax(0,1fr);padding:4px 7px 4px 0;border-bottom:1px solid #edf1f4}.code-row.current{background:#fff2cc;border-left:4px solid #c79323}.number{text-align:right;padding-right:8px;color:#8196a6;font:12px/1.8 ui-monospace,monospace}.code-row code{display:block;white-space:pre-wrap;overflow-wrap:anywhere;font:var(--code-size,15px)/1.55 ui-monospace,monospace}.code-row p{font:13px/1.5 system-ui;margin:4px 0 5px;color:#476079}.source-tools{display:flex;gap:7px;flex-wrap:wrap}.source-tools select{max-width:100%;flex:1}.source-path{font-size:12px;overflow-wrap:anywhere;margin:8px 0}details{margin-top:16px}summary{cursor:pointer;font-weight:600}.supplement{max-width:1200px;padding:16px;background:white;margin-top:16px;border-radius:10px}.tag{display:inline-block;background:#e4f3ef;color:#086958;padding:2px 8px;border-radius:5px;font-size:12px}.note{font-size:13px;color:#597084}.measurements{font-size:14px;white-space:pre-wrap}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #4393c7;outline-offset:2px}@media(max-width:950px){header,main{padding:12px}.layout{grid-template-columns:1fr}#code{height:60vh}.intro{font-size:14px}}'''
PAGES=[
 {'id':'structured-primal-inlining','model':'primal','title':'结构化 primal：让调用点看到完整事件处理体','entry':'Mwpm::process_event(const MwpmEvent&) → void','intro':'事件分派与交替树操作从 .cc 移入被头文件包含的 .inl。演示边界事件从入口到返回的状态更新；算法顺序与原实现一致。无 LTO 构建可在本翻译单元内看见函数体，实际内联选择仍由编译器决定。','scenes':[('leaf','边界命中：单个根'),('child','边界命中：含一个匹配子节点'),('none','NO_EVENT：无状态更新')],'sources':['structured_dispatch','structured_boundary','structured_shatter','structured_root'],'boundary':'演示范围：primal 分派、边界处理、树递归回收与已为根时的 become_root。set_region_frozen 是明确的 dual 辅助调用边界；其队列内部不在本页模拟。其他碰撞/裂解分支可查源码但不提供执行动画。','evidence':'原819-call矩阵没有独立内联消融。后续只禁止一个边界处理函数内联，见报告中的未采纳变体；它没有隔离全部11个Mwpm与16个交替树函数的内联效果。源码可见性是机制事实，组合收益不能单独归给内联。'},
 {'id':'certified-generic-predecode','model':'generic','title':'通用图预解码：tight 匹配与可撤销的部分结果','entry':'OneHopPredecoder::run_one(size_t) → void','intro':'非活动节点势能为0；每次增长保持 y_u+y_v≤w，边界边保持 y_u≤w，只接收 tight 边。所有 seed 完整匹配时，匹配权重达到 dual 下界；不完整时保留全部 singleton 与暂配，交给完整 blossom 继续求解。','scenes':[('pair','两个 seed：tight 配对完成'),('partial','三个 seed：部分结果导入'),('untight','非 tight 边：保持未匹配'),('boundary','单 seed：边界匹配')],'sources':['generic_match','generic_grow','generic_completion','generic_import','generic_dispatch'],'boundary':'演示入口是 run_one(0)，prepare 和候选表构建是已完成前置状态。随后展示外层 complete 判断以及不完整状态的导入边界；完整 blossom 后续求解不在本页模拟。演示整数图不是性能采样输入。','evidence':'负权端点先异或规范化，最终补回负权摘要；correlation 两遍重加权在整个 scope 中关闭此预解码器。大于64个 observable 使用路径提取。对任意 T-join，w(T)≥Σ_seed y_s；完整 tight 匹配让每个 seed 恰使用一条匹配边，达到同一下界。部分匹配尚无此完成证书，必须交给完整求解器。证明不依赖固定 stencil。'},
 {'id':'bounded-density-gate','model':'gate','title':'局部密度门控：有界探测与循环内除法外提','entry':'OneHopPredecoder::should_skip_sparse_high_degree() const → bool','intro':'只在活动节点平均度至少32且没有直接边界时采样。节点预算为 min(8,ceil(seed数/4))，每节点最多32条邻边；活动邻居不足1/8时直接创建普通 roots。类内 seed_index 和商余数递推减轻门控本身的固定开销。','scenes':[('sparse','稀疏高阶：回退'),('remainder','17个 seed：余数进位'),('mixed','混合度数：短邻接全扫'),('dense','稠密活动分量：保留预解码'),('threshold','恰好1/8：严格阈值'),('low','低度：提前返回'),('boundary','直接边界：提前返回'),('empty','空 syndrome')],'sources':['density_gate','seed_index','generic_import'],'boundary':'完整运行门控函数直到 bool 返回。图中显示实际被采样的邻接槽；分母 sampled 在每个邻域结束后累加。递推位置另外用 floor(k*N/count) 核对。未运行的预解码或完整求解器是下一阶段。','evidence':'这是路径选择的性能启发式。回退复用已验证的规范化 syndrome，保持完整求解器语义。循环外仍有可变除法；只说明源级递推消除了逐样本除法，机器码证据另附与最终源码一致的 Release 库对象反汇编，范围和来源见报告。'}]
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
summary_path=R/'summary.json'
if not summary_path.exists():summary_path.write_text(json.dumps({'schema':1,'status':'collecting','implementation_commit':M['candidate_commit'],'collector_commits':['edd29b6780713dc78f6a99d67c4c4d192e9c52b5','0ad4fde55adaae41e337a6ee89974703c07bb8cd'],'official_revision':'e27b8c6a5f5ba10fb74d4ebb29822f2df5e12bcd','migration_source_revision':M['origin_commit'],'generic':None,'structured':None,'evidence':[]},indent=2)+'\n')
S=json.loads(summary_path.read_text());coverage=[]
for page in PAGES:
 data={'model':page['model'],'sources':{k:A['excerpts'][k] for k in page['sources']},'origin':{'excerpts':{k:M['excerpts'][k] for k in page['sources']}}}
 options=''.join(f'<option value="{key}">{html.escape(label)}</option>' for key,label in page['scenes'])
 source_options=''.join(f'<option value="{k}">{html.escape(k)}</option>' for k in page['sources'])
 numbers='正式结果正在采集；本页没有写入试验轮次的性能值。'
 group=S.get('structured') if page['model']=='primal' else S.get('generic')
 if group:numbers=json.dumps(group.get('overview',{}),ensure_ascii=False,indent=2)
 serialized=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
 document=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{page['title']}</title><style>{css}</style><header><a href="../index.html">← 迁移复核报告</a><h1>{page['title']}</h1><p class="identity">{page['entry']} · 源码 edd29b678071 · <span class="tag">可计算的代码语义演示</span></p><p class="intro">{page['intro']}</p><div class="controls"><select id="scene" aria-label="演示输入">{options}</select><button id="play">播放</button><button id="prev">上一步</button><button id="next">下一步</button><button id="reset">重置</button><input id="progress" type="range" min="0" value="0" aria-label="执行进度"><span id="position"></span></div></header><main><div class="layout"><section class="panel"><h2>运行状态</h2><div id="message" aria-live="polite"></div><svg id="graph" role="img" aria-label="当前函数执行状态图"></svg><pre id="state"></pre><p class="note">播放速度不表示CPU周期。图节点、整数和帧数均为演示输入。</p></section><section class="panel"><div class="source-tools"><select id="source" aria-label="源码函数">{source_options}</select><button id="smaller" aria-label="缩小代码字号">A−</button><button id="larger" aria-label="放大代码字号">A+</button></div><p id="source-path" class="source-path"></p><div id="code" tabindex="0" aria-label="原始源码与逐行解释"></div></section></div><section class="supplement"><h2>执行边界与证据</h2><p>{page['boundary']}</p><p>{page['evidence']}</p><details><summary>固定来源、前后代码与结果口径</summary><p>原始来源 {M['origin_commit']}；本地恢复标签 source-2411603 → {M['recovered_commit']}。候选 {M['candidate_commit']}。</p><p><a href="../code-diff/index.html">打开本次函数范围完整代码对照</a> · <a href="../code-diff/diff.patch">原始 patch</a> · <a href="../sources/manifest.json">原文件与节选映射</a> · <a href="../sources/line-explanations.json">逐行解释清单</a></p><p>上游主比较采用 official e27 / candidate。通用图迁移实验单列 source241 / candidate，没有对应同轮 official 任意图数据。</p><pre class="measurements">{html.escape(numbers)}</pre></details></section></main><script>window.MECHANISM_DATA={serialized};</script><script>{js}</script></html>'''
 path=R/'mechanisms'/(page['id']+'.html');path.write_text(document)
 coverage.append({'optimization_id':page['id'],'title':page['title'],'decision':'adopted','html':{'path':str(path.relative_to(R)),'sha256':sha(path)},'publication':{'kind':'offline','external_publishing_requested':False},'interaction':{'entry':page['entry'],'model':page['model'],'scenarios':page['scenes'],'boundary':page['boundary']},'source_scopes':page['sources'],'line_explanations':{'path':'sources/line-explanations.json','sha256':sha(R/'sources/line-explanations.json')},'summary':{'path':'summary.json','sha256':sha(summary_path)},'evidence_scope':page['evidence'],'verification':{'source_and_line_mapping':'passed','browser':'pending browser verification for this rendering'}})
(R/'optimization-coverage.json').write_text(json.dumps({'schema':1,'revision':1,'optimizations':coverage},indent=2,ensure_ascii=False)+'\n')
print('Generated 3 standalone offline mechanism pages; browser verification pending')
